// 배부 양식 생성기 조각 — `check -- prose` 가 문자열 속 문장을 보는가.
// 경로의 `docx/make/` 로 생성기라고 알아본다. 주석의 물러난 말(돌렸다 · 쟀다 · '인용')은 보지 않는다.
const {makeDocument} = require('../make_sw_template');

makeDocument({
    s1: {
        purpose: [
            "같은 자로 맞춘 뒤에 돌렸다.",                    // 물러난 말(돌리다)
            "얼마나 흩어져 있는지를 쟀다.",                   // 금지 낱말(재다) — html 검사의 BANNED_WORDS
            "모델은 '승인'이라는 말을 하지 않는다.",           // 곧은따옴표
            "※ 스크린샷: 결과 화면 [위 빈 공간에 첨부]",       // 라벨(※)
            "💡 먼저 확인할 것",                               // 이모지
            "「승인」과 「거절」로 나뉜다.",                   // 걸리면 안 된다
        ],
    },
    s3: {
        // 코드인 칸은 보지 않는다 — 프로그램의 문자열을 그대로 적는 자리다.
        flowchart: [
            "   obesity ≤ 10   →  '정상' 출력",
        ],
        pseudocode: [
            "  출력('정상')",
        ],
    },
    s4: {
        code: [
            "print('잘못된 입력입니다. 다시 돌려 주세요.')",
        ],
    },
});

if (!module) throw new Error("출력 경로가 없다. out('그룹', '파일명.docx')를 넘긴다");
